    replace_bytes(haystack, limit, re.captures_iter(haystack), |caps, out| {
        out.extend_from_slice(replacement);
        let _ = caps;
    })
}

fn replace_bytes<'a, I, F>(haystack: &'a [u8], limit: usize, captures: I, mut write_replacement: F) -> Vec<u8>
where
    I: IntoIterator<Item = Captures<'a>>,
    F: FnMut(&Captures<'a>, &mut Vec<u8>),
{
    let mut output = Vec::with_capacity(haystack.len());
    let mut last_end = 0;
    let mut replacements = 0usize;

